// Package problemdata persists validated testcase datasets as immutable versions.
// Storage keys are generated by the server, never derived from uploaded names.
package problemdata

import (
	"bytes"
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
	"sync"
	"unicode/utf8"

	"biue/internal/testcase"
)

var (
	ErrInvalid     = errors.New("invalid problem dataset or storage key")
	ErrNotFound    = errors.New("problem dataset not found")
	ErrCorrupt     = errors.New("problem dataset integrity check failed")
	ErrUnavailable = errors.New("problem dataset storage unavailable")
	caseIDPattern  = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$`)
)

const maxManifestBytes = 1 << 20

// Store owns a handle to a dedicated directory. Close it when the process exits.
// Callers must not modify a dataset's slices until Write returns. The database
// must record a returned key before exposing that version to readers. Clear is
// reserved for fully authenticated test-center initialization.
type Store struct {
	mu     sync.RWMutex
	root   *os.Root
	closed bool
	random io.Reader
	rename func(string, string) error
}

type manifest struct {
	FormatVersion int            `json:"format_version"`
	Digest        string         `json:"digest"`
	CaseCount     int            `json:"case_count"`
	TotalBytes    int64          `json:"total_bytes"`
	TotalScore    int64          `json:"total_score"`
	Cases         []manifestCase `json:"cases"`
}

type manifestCase struct {
	ID           string `json:"id"`
	Score        int64  `json:"score"`
	InputBytes   int64  `json:"input_bytes"`
	OutputBytes  int64  `json:"output_bytes"`
	InputSHA256  string `json:"input_sha256"`
	OutputSHA256 string `json:"output_sha256"`
}

// New creates the configured storage directory if needed. Configuration is
// trusted, but an empty path, filesystem root or symlink as the final directory
// is rejected. Existing versions are preserved when reopening the store.
func New(directory string) (*Store, error) {
	if strings.TrimSpace(directory) == "" {
		return nil, ErrInvalid
	}
	absolute, err := filepath.Abs(directory)
	if err != nil || filepath.Dir(absolute) == absolute {
		return nil, ErrInvalid
	}
	if err := os.MkdirAll(absolute, 0750); err != nil {
		return nil, ErrUnavailable
	}
	info, err := os.Lstat(absolute)
	if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
		return nil, ErrUnavailable
	}
	root, err := os.OpenRoot(absolute)
	if err != nil {
		return nil, ErrUnavailable
	}
	return &Store{root: root, random: rand.Reader, rename: root.Rename}, nil
}

func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil
	}
	s.closed = true
	if err := s.root.Close(); err != nil {
		return ErrUnavailable
	}
	return nil
}

// Clear removes every published and incomplete version key owned by this store.
// It does not remove unrelated files or directories from the configured root.
func (s *Store) Clear(ctx context.Context) (int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return 0, ErrUnavailable
	}
	if err := contextError(ctx); err != nil {
		return 0, err
	}
	directory, err := s.root.Open(".")
	if err != nil {
		return 0, storageError(ctx)
	}
	defer directory.Close()
	entries, err := directory.ReadDir(-1)
	if err != nil {
		return 0, storageError(ctx)
	}
	removed := 0
	for _, entry := range entries {
		if err := contextError(ctx); err != nil {
			return removed, err
		}
		if !validHex(entry.Name(), 32) {
			continue
		}
		info, err := s.root.Lstat(entry.Name())
		if err != nil {
			return removed, storageError(ctx)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			continue
		}
		if err := s.root.RemoveAll(entry.Name()); err != nil {
			return removed, storageError(ctx)
		}
		removed++
	}
	if err := syncDirectory(s.root); err != nil {
		return removed, storageError(ctx)
	}
	return removed, contextError(ctx)
}

// Write stages a complete version, then atomically renames its data directory.
// An exclusive random parent directory reserves the key before any files are
// written, so publication cannot replace an existing version, even on platforms
// whose Rename would otherwise replace an empty target directory.
func (s *Store) Write(ctx context.Context, dataset testcase.Dataset) (string, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if s.closed {
		return "", ErrUnavailable
	}
	if err := contextError(ctx); err != nil {
		return "", err
	}
	m, err := describe(ctx, dataset)
	if err != nil {
		return "", err
	}
	key, err := s.reserve()
	if err != nil {
		return "", err
	}
	published := false
	defer func() {
		if !published {
			// key is an exclusively created, validated child of this os.Root.
			_ = s.root.RemoveAll(key)
		}
	}()
	if err := s.root.Mkdir(key+"/.pending", 0750); err != nil {
		return "", storageError(ctx)
	}
	stage, err := s.root.OpenRoot(key + "/.pending")
	if err != nil {
		return "", storageError(ctx)
	}
	stageOpen := true
	defer func() {
		if stageOpen {
			_ = stage.Close()
		}
	}()
	for i, c := range dataset.Cases {
		if err := writeFile(ctx, stage, caseFile(i, "in"), c.Input); err != nil {
			return "", err
		}
		if err := writeFile(ctx, stage, caseFile(i, "out"), c.Output); err != nil {
			return "", err
		}
	}
	raw, err := json.Marshal(m)
	if err != nil || len(raw) > maxManifestBytes {
		return "", ErrInvalid
	}
	if err := writeFile(ctx, stage, "manifest.json", raw); err != nil {
		return "", err
	}
	if err := syncDirectory(stage); err != nil {
		return "", storageError(ctx)
	}
	closeErr := stage.Close()
	stageOpen = false
	if closeErr != nil {
		return "", storageError(ctx)
	}
	if err := contextError(ctx); err != nil {
		return "", err
	}
	if err := s.rename(key+"/.pending", key+"/data"); err != nil {
		return "", storageError(ctx)
	}
	published = true // Never remove a published directory, including Sync failures.
	parent, err := s.root.OpenRoot(key)
	if err != nil {
		return "", storageError(ctx)
	}
	syncErr := syncDirectory(parent)
	closeErr = parent.Close()
	if syncErr != nil || closeErr != nil || syncDirectory(s.root) != nil {
		return "", storageError(ctx)
	}
	if err := contextError(ctx); err != nil {
		return "", err
	}
	return key, nil
}

func (s *Store) reserve() (string, error) {
	for range 8 {
		var random [16]byte
		if _, err := io.ReadFull(s.random, random[:]); err != nil {
			return "", ErrUnavailable
		}
		key := hex.EncodeToString(random[:])
		if err := s.root.Mkdir(key, 0750); err == nil {
			return key, nil
		} else if !errors.Is(err, os.ErrExist) {
			return "", ErrUnavailable
		}
	}
	return "", ErrUnavailable
}

// Read verifies the manifest, exact file set, file sizes, per-file hashes, totals
// and versioned dataset fingerprint. It never trusts a filename in a manifest.
// A caller reading a database version must additionally compare Digest against
// that database row: a filesystem manifest alone is not the source of truth.
func (s *Store) Read(ctx context.Context, key string) (testcase.Dataset, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if s.closed {
		return testcase.Dataset{}, ErrUnavailable
	}
	if err := contextError(ctx); err != nil {
		return testcase.Dataset{}, err
	}
	if !validHex(key, 32) {
		return testcase.Dataset{}, ErrInvalid
	}
	for _, name := range []string{key, key + "/data"} {
		info, err := s.root.Lstat(name)
		if errors.Is(err, os.ErrNotExist) {
			return testcase.Dataset{}, ErrNotFound
		}
		if err != nil {
			return testcase.Dataset{}, storageError(ctx)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return testcase.Dataset{}, ErrCorrupt
		}
	}
	data, err := s.root.OpenRoot(key + "/data")
	if err != nil {
		return testcase.Dataset{}, storageError(ctx)
	}
	defer data.Close()
	raw, err := readFile(ctx, data, "manifest.json", maxManifestBytes, -1)
	if err != nil {
		return testcase.Dataset{}, err
	}
	var m manifest
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if !utf8.Valid(raw) || decoder.Decode(&m) != nil {
		return testcase.Dataset{}, ErrCorrupt
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) || !validManifest(m) {
		return testcase.Dataset{}, ErrCorrupt
	}
	if err := checkEntries(data, len(m.Cases)); err != nil {
		return testcase.Dataset{}, err
	}
	dataset := testcase.Dataset{Cases: make([]testcase.Case, 0, len(m.Cases)), TotalBytes: m.TotalBytes, TotalScore: m.TotalScore}
	for i, c := range m.Cases {
		input, err := readFile(ctx, data, caseFile(i, "in"), c.InputBytes, c.InputBytes)
		if err != nil {
			return testcase.Dataset{}, err
		}
		output, err := readFile(ctx, data, caseFile(i, "out"), c.OutputBytes, c.OutputBytes)
		if err != nil {
			return testcase.Dataset{}, err
		}
		if checksum(input) != c.InputSHA256 || checksum(output) != c.OutputSHA256 {
			return testcase.Dataset{}, ErrCorrupt
		}
		dataset.Cases = append(dataset.Cases, testcase.Case{ID: c.ID, Input: input, Output: output, Score: c.Score})
	}
	dataset.Digest = testcase.Fingerprint(dataset.Cases)
	if hex.EncodeToString(dataset.Digest[:]) != m.Digest {
		return testcase.Dataset{}, ErrCorrupt
	}
	if err := contextError(ctx); err != nil {
		return testcase.Dataset{}, err
	}
	return dataset, nil
}

func describe(ctx context.Context, dataset testcase.Dataset) (manifest, error) {
	m := manifest{FormatVersion: 1, Digest: hex.EncodeToString(dataset.Digest[:]), CaseCount: len(dataset.Cases),
		TotalBytes: dataset.TotalBytes, TotalScore: dataset.TotalScore, Cases: make([]manifestCase, 0, len(dataset.Cases))}
	limits := testcase.DefaultLimits()
	if len(dataset.Cases) == 0 || len(dataset.Cases) > limits.MaxCases {
		return manifest{}, ErrInvalid
	}
	for _, c := range dataset.Cases {
		if err := contextError(ctx); err != nil {
			return manifest{}, err
		}
		m.Cases = append(m.Cases, manifestCase{ID: c.ID, Score: c.Score, InputBytes: int64(len(c.Input)), OutputBytes: int64(len(c.Output)),
			InputSHA256: checksum(c.Input), OutputSHA256: checksum(c.Output)})
	}
	if !validManifest(m) || testcase.Fingerprint(dataset.Cases) != dataset.Digest {
		return manifest{}, ErrInvalid
	}
	if err := contextError(ctx); err != nil {
		return manifest{}, err
	}
	return m, nil
}

func validManifest(m manifest) bool {
	limits := testcase.DefaultLimits()
	if m.FormatVersion != 1 || !validHex(m.Digest, 64) || m.CaseCount != len(m.Cases) || m.CaseCount == 0 || m.CaseCount > limits.MaxCases {
		return false
	}
	folded := make(map[string]bool, len(m.Cases))
	var totalBytes, totalScore int64
	for i, c := range m.Cases {
		fold := strings.ToLower(c.ID)
		if !validID(c.ID) || i > 0 && c.ID <= m.Cases[i-1].ID || folded[fold] ||
			c.Score < 0 || c.Score > math.MaxInt64-totalScore ||
			c.InputBytes < 0 || c.InputBytes > limits.MaxFileBytes || c.OutputBytes < 0 || c.OutputBytes > limits.MaxFileBytes ||
			!validHex(c.InputSHA256, 64) || !validHex(c.OutputSHA256, 64) {
			return false
		}
		folded[fold] = true
		totalBytes += c.InputBytes + c.OutputBytes
		totalScore += c.Score
		if totalBytes > limits.MaxTotalBytes {
			return false
		}
	}
	return totalScore > 0 && m.TotalBytes == totalBytes && m.TotalScore == totalScore
}

func validID(id string) bool {
	if !caseIDPattern.MatchString(id) {
		return false
	}
	upper := strings.ToUpper(id)
	switch upper {
	case "CON", "PRN", "AUX", "NUL":
		return false
	}
	return !(len(upper) == 4 && (strings.HasPrefix(upper, "COM") || strings.HasPrefix(upper, "LPT")) && upper[3] >= '1' && upper[3] <= '9')
}

func validHex(value string, length int) bool {
	if len(value) != length {
		return false
	}
	for _, c := range value {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

func checksum(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func caseFile(index int, extension string) string { return fmt.Sprintf("%06d.%s", index+1, extension) }

func writeFile(ctx context.Context, root *os.Root, name string, data []byte) error {
	if err := contextError(ctx); err != nil {
		return err
	}
	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0640)
	if err != nil {
		return storageError(ctx)
	}
	defer f.Close()
	for len(data) > 0 {
		if err := contextError(ctx); err != nil {
			return err
		}
		n, err := f.Write(data[:min(len(data), 32<<10)])
		if err != nil || n == 0 {
			return storageError(ctx)
		}
		data = data[n:]
	}
	if f.Sync() != nil {
		return storageError(ctx)
	}
	if f.Close() != nil {
		return storageError(ctx)
	}
	return contextError(ctx)
}

func readFile(ctx context.Context, root *os.Root, name string, maxBytes, expectedBytes int64) ([]byte, error) {
	if err := contextError(ctx); err != nil {
		return nil, err
	}
	info, err := root.Lstat(name)
	if err != nil || !info.Mode().IsRegular() || info.Size() > maxBytes || expectedBytes >= 0 && info.Size() != expectedBytes {
		return nil, ErrCorrupt
	}
	f, err := root.Open(name)
	if err != nil {
		return nil, storageError(ctx)
	}
	defer f.Close()
	info, err = f.Stat()
	if err != nil || !info.Mode().IsRegular() {
		return nil, ErrCorrupt
	}
	raw, err := io.ReadAll(io.LimitReader(contextReader{ctx: ctx, src: f}, maxBytes+1))
	if err := contextError(ctx); err != nil {
		return nil, err
	}
	if err != nil || int64(len(raw)) > maxBytes || expectedBytes >= 0 && int64(len(raw)) != expectedBytes {
		return nil, ErrCorrupt
	}
	return raw, nil
}

func checkEntries(root *os.Root, cases int) error {
	directory, err := root.Open(".")
	if err != nil {
		return ErrUnavailable
	}
	defer directory.Close()
	entries, err := directory.ReadDir(cases*2 + 2)
	if err != nil && !errors.Is(err, io.EOF) || len(entries) != cases*2+1 {
		return ErrCorrupt
	}
	for _, entry := range entries {
		if !entry.Type().IsRegular() {
			return ErrCorrupt
		}
	}
	// All expected names are opened separately; equal count rejects extra files.
	return nil
}

func syncDirectory(root *os.Root) error {
	// Windows does not support fsync on directory handles. Files themselves are
	// always synced; POSIX also persists directories before/after publication.
	if runtime.GOOS == "windows" {
		return nil
	}
	directory, err := root.Open(".")
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func contextError(ctx context.Context) error {
	if ctx == nil {
		return ErrInvalid
	}
	return ctx.Err()
}

func storageError(ctx context.Context) error {
	if err := contextError(ctx); err != nil {
		return err
	}
	return ErrUnavailable
}

type contextReader struct {
	ctx context.Context
	src io.Reader
}

func (r contextReader) Read(p []byte) (int, error) {
	if err := r.ctx.Err(); err != nil {
		return 0, err
	}
	n, err := r.src.Read(p[:min(len(p), 32<<10)])
	if canceled := r.ctx.Err(); canceled != nil {
		return n, canceled
	}
	return n, err
}
